body.script:
//
(function() {
  'use strict';

  /* SECTION: FEED CACHE (15 min TTL) */
  var FeedCache = {
    TTL: 15 * 60 * 1000,
    key: function(k) { return 'ln_fc_' + k; },
    get: function(k) {
      try {
        var raw = localStorage.getItem(this.key(k));
        if (!raw) return null;
        var obj = JSON.parse(raw);
        if (!obj || !obj.t) return null;
        if (Date.now() - obj.t > this.TTL) { localStorage.removeItem(this.key(k)); return null; }
        return obj.d;
      } catch(e) { return null; }
    },
    set: function(k, d) {
      try {
        var json = JSON.stringify({ t: Date.now(), d: d });
        if (json.length < 250000) localStorage.setItem(this.key(k), json);
      } catch(e) {}
    }
  };
  function cachedFetchJson(url) {
    var hit = FeedCache.get(url);
    if (hit) return Promise.resolve(hit);
    return fetch(url, { cache: 'default', credentials: 'omit' })
      .then(function(r) { return r.json(); })
      .then(function(d) { FeedCache.set(url, d); return d; });
  }

  /* SECTION: MOBILE MENU & SEARCH OVERLAY */
  var hamburger = document.getElementById('hamburger-btn');
  var mobileMenu = document.getElementById('mobile-menu');
  var overlay = document.getElementById('overlay');
  var mobileClose = document.getElementById('mobile-close');
  var searchMobileBtn = document.getElementById('search-mobile-btn');
  var searchOverlay = document.getElementById('search-overlay');
  var searchClose = document.getElementById('search-close');

  function closeMobileMenu() {
    if (mobileMenu) mobileMenu.classList.remove('open');
    if (overlay) overlay.classList.remove('show');
    document.body.style.overflow = '';
  }
  function closeSearch() {
    if (searchOverlay) searchOverlay.classList.remove('open');
    document.body.style.overflow = '';
  }
  if (hamburger) hamburger.addEventListener('click', function() {
    mobileMenu.classList.toggle('open');
    overlay.classList.toggle('show');
    document.body.style.overflow = mobileMenu.classList.contains('open') ? 'hidden' : '';
  });
  if (mobileClose) mobileClose.addEventListener('click', closeMobileMenu);
  if (overlay) overlay.addEventListener('click', function() { closeMobileMenu(); closeSearch(); });
  if (searchMobileBtn) searchMobileBtn.addEventListener('click', function() {
    searchOverlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  });
  if (searchClose) searchClose.addEventListener('click', closeSearch);

  document.querySelectorAll('.mobile-menu nav li.has-children > a').forEach(function(link) {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      this.parentElement.classList.toggle('open');
    });
  });

  /* SECTION: SOCIAL ICONS (Header) */
  document.querySelectorAll('#social-networks-list a').forEach(function(link) {
    var url = (link.getAttribute('href') || '').toLowerCase();
    var name = (link.getAttribute('data-name') || '').toLowerCase();
    var cls = 'net-other', icon = 'fas fa-link';
    if (url.indexOf('wa.me') !== -1 || url.indexOf('whatsapp') !== -1 || name.indexOf('whatsapp') !== -1) { cls = 'net-whatsapp'; icon = 'fab fa-whatsapp'; }
    else if (url.indexOf('t.me') !== -1 || url.indexOf('telegram') !== -1 || name.indexOf('telegram') !== -1) { cls = 'net-telegram'; icon = 'fab fa-telegram-plane'; }
    else if (url.indexOf('youtube') !== -1 || url.indexOf('youtu.be') !== -1 || name.indexOf('youtube') !== -1) { cls = 'net-youtube'; icon = 'fab fa-youtube'; }
    link.classList.add(cls);
    link.innerHTML = '<i class="' + icon + '"></i>';
  });

  /* SECTION: WHATSAPP TOOLTIP */
  var tooltip = document.getElementById('whatsapp-tooltip');
  var whatsappBtn = document.getElementById('whatsapp-float-btn');
  setTimeout(function() {
    if (tooltip) tooltip.classList.add('show');
    setTimeout(function() { if (tooltip) tooltip.classList.remove('show'); }, 6000);
  }, 7000);
  if (whatsappBtn && tooltip) {
    whatsappBtn.addEventListener('mouseenter', function() { tooltip.classList.add('show'); });
    whatsappBtn.addEventListener('mouseleave', function() { tooltip.classList.remove('show'); });
  }

  /* SECTION: BACK TO TOP */
  var backToTop = document.getElementById('back-to-top');
  var progressCircle = document.querySelector('.progress-ring__circle');
  if (progressCircle && backToTop) {
    var radius = progressCircle.r.baseVal.value;
    var circumference = radius * 2 * Math.PI;
    progressCircle.style.strokeDasharray = circumference + ' ' + circumference;
    progressCircle.style.strokeDashoffset = circumference;
    window.addEventListener('scroll', function() {
      var scrollThreshold = document.documentElement.scrollHeight * 0.35;
      if (window.scrollY > scrollThreshold) backToTop.classList.add('show');
      else backToTop.classList.remove('show');
      var max = document.documentElement.scrollHeight - window.innerHeight;
      var pct = max > 0 ? window.scrollY / max : 0;
      progressCircle.style.strokeDashoffset = circumference - pct * circumference;
    }, { passive: true });
    backToTop.addEventListener('click', function() { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  }

  /* SECTION: REVEAL OBSERVER */
  window.__revealObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('reveal-in');
        window.__revealObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
  window.observeReveals = function(root) {
    (root || document).querySelectorAll('.psp-card:not(.reveal-in):not(.observed)').forEach(function(card, i) {
      card.classList.add('observed');
      card.style.animationDelay = (i % 12) * 60 + 'ms';
      window.__revealObserver.observe(card);
    });
  };

  /* SECTION: COOKIE + ADBLOCK GATE */
  var CONSENT_KEY = 'cookieConsent';
  function showModal(id) {
    var el = document.getElementById(id);
    if (!el) return;
    el.classList.add('show');
    document.body.style.overflow = 'hidden';
  }
  function hideModal(id) {
    var el = document.getElementById(id);
    if (!el) return;
    el.classList.remove('show');
    document.body.style.overflow = '';
  }

  function detectAdblock() {
    return new Promise(function(resolve) {
      // Restaurado a v4.6: Tamaño 300x250 y clases completas para evitar falsos positivos en navegadores con protección de rastreo.
      var bait = document.createElement('div');
      bait.className = 'adsbox ad-banner ad-placement pub_300x250 pub_300x250m text-ad textAd text_ad text-ads text-ad-links ad-unit adsbygoogle';
      bait.style.cssText = 'position:absolute!important;left:-9999px!important;top:-9999px!important;width:300px!important;height:250px!important;';
      bait.innerHTML = '&nbsp;';
      document.body.appendChild(bait);

      setTimeout(function() {
        var blocked = false;
        try {
          var cs = getComputedStyle(bait);
          blocked = bait.offsetHeight === 0 || 
                    bait.clientHeight === 0 || 
                    bait.offsetParent === null || 
                    cs.display === 'none' || 
                    cs.visibility === 'hidden' || 
                    parseFloat(cs.opacity) === 0;
        } catch(e) { blocked = false; }

        if (bait.parentNode) bait.parentNode.removeChild(bait);

        resolve(blocked);
      }, 350);
    });
  }

  var adblockPollTimer = null;
  function startAdblockPoll() {
    if (adblockPollTimer) return;
    var attempts = 0;
    adblockPollTimer = setInterval(function() {
      attempts++;
      if (attempts > 40) { clearInterval(adblockPollTimer); adblockPollTimer = null; return; }
      detectAdblock().then(function(blocked) {
        if (!blocked) {
          clearInterval(adblockPollTimer);
          adblockPollTimer = null;
          hideModal('adblock-modal');
        }
      });
    }, 3000);
  }

  function gateAfterAccept() {
    detectAdblock().then(function(blocked) {
      if (blocked) { showModal('adblock-modal'); startAdblockPoll(); }
      else { hideModal('adblock-modal'); }
    });
  }

  function initConsentGate() {
    var path = window.location.pathname;
    var isLegalPage = path.indexOf('/p/cookie-policy') !== -1 || path.indexOf('/p/privacy-policy') !== -1 || path.indexOf('/p/legal-notice') !== -1;

    var consent = localStorage.getItem(CONSENT_KEY);
    var banner = document.getElementById('cookie-banner');

    if (isLegalPage) {
      // En páginas legales nunca bloqueamos, pero mostramos el banner para que acepten si quieren
      hideModal('cookie-reject-modal');
      hideModal('adblock-modal');
      if (consent !== 'accepted') {
        if (banner) banner.style.display = 'flex';
      } else {
        if (banner) banner.style.display = 'none';
      }
      return;
    }

    if (!consent) {
      if (banner) banner.style.display = 'flex';
      return;
    }
    if (consent === 'rejected') {
      showModal('cookie-reject-modal');
      return;
    }
    if (banner) banner.style.display = 'none';
    gateAfterAccept();
  }

  var acceptBtn = document.getElementById('cookie-accept');
  var rejectBtn = document.getElementById('cookie-reject');
  var rejectAcceptBtn = document.getElementById('reject-accept');
  var adblockReloadBtn = document.getElementById('adblock-reload');

  if (acceptBtn) acceptBtn.addEventListener('click', function() {
    localStorage.setItem(CONSENT_KEY, 'accepted');
    var banner = document.getElementById('cookie-banner');
    if (banner) banner.style.display = 'none';
    gateAfterAccept();
  });
  if (rejectBtn) rejectBtn.addEventListener('click', function() {
    localStorage.setItem(CONSENT_KEY, 'rejected');
    var banner = document.getElementById('cookie-banner');
    if (banner) banner.style.display = 'none';
    showModal('cookie-reject-modal');
  });
  if (rejectAcceptBtn) rejectAcceptBtn.addEventListener('click', function() {
    localStorage.setItem(CONSENT_KEY, 'accepted');
    hideModal('cookie-reject-modal');
    gateAfterAccept();
  });
  if (adblockReloadBtn) adblockReloadBtn.addEventListener('click', function() { location.reload(); });

  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState !== 'visible') return;
    if (localStorage.getItem(CONSENT_KEY) !== 'accepted') return;
    var modal = document.getElementById('adblock-modal');
    if (modal && modal.classList.contains('show')) {
      detectAdblock().then(function(blocked) {
        if (!blocked) {
          hideModal('adblock-modal');
          if (adblockPollTimer) { clearInterval(adblockPollTimer); adblockPollTimer = null; }
        }
      });
    }
  });

  window.addEventListener('load', function() { setTimeout(initConsentGate, 350); });

  /* SECTION: TICKER */
  var tickerContent = document.getElementById('ticker-content');
  if (tickerContent) {
    cachedFetchJson('/feeds/posts/default?alt=json&max-results=6')
      .then(function(data) {
        var posts = (data.feed && data.feed.entry) ? data.feed.entry : [];
        if (!posts.length) { tickerContent.innerHTML = '<span style="color:#8b8ba8;font-size:0.82rem;">No games yet.</span>'; return; }
        var postsDup = posts.concat(posts);
        var html = '';
        postsDup.forEach(function(post) {
          var title = post.title.$t;
          var postUrl = '';
          for (var i = 0; i < post.link.length; i++) { if (post.link[i].rel === 'alternate') { postUrl = post.link[i].href; break; } }
          var thumb = '';
          if (post.media$thumbnail && post.media$thumbnail.url) thumb = post.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/s100/');
          html += '<a href="' + postUrl + '" class="ticker-item">';
          if (thumb) html += '<img src="' + thumb + '" alt="' + title + '" loading="lazy" decoding="async"/>';
          html += '<span>' + title + '</span></a>';
        });
        tickerContent.innerHTML = html;
      })
      .catch(function() { tickerContent.innerHTML = '<span style="color:#ff2d95;font-size:0.82rem;">Error loading.</span>'; });
  }

  /* SECTION: SIDEBAR WIDGETS */
  function generateCardHTML(entry) {
    var title = entry.title.$t;
    var link = '#';
    for (var i = 0; i < entry.link.length; i++) { if (entry.link[i].rel === 'alternate') { link = entry.link[i].href; break; } }
    var thumb = '';
    if (entry.media$thumbnail && entry.media$thumbnail.url) thumb = entry.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/s600/');
    var rating = '0.0', weight = '', categories = [], hasPSP = false;
    (entry.category || []).forEach(function(cat) {
      var term = cat.term;
      if (term.toUpperCase() === 'PSP') hasPSP = true;
      else if (/^v\d+(\.\d+)?$/.test(term)) rating = term.substring(1);
      else if (/^p\d+(\.\d+)?$/.test(term)) weight = term.substring(1);
      else categories.push(term);
    });
    var pspTag = hasPSP ? '<span class="tag-psp">PSP</span>' : '';
    var catTag = categories.length ? '<span class="tag-cat">' + categories[0] + '</span>' : '';
    var ratingHTML = rating !== '0.0' ? '<span class="stat-rating"><i class="fas fa-star"></i> ' + rating + '</span>' : '';
    var weightHTML = '';
    if (weight) {
      var wn = parseFloat(weight), wu = wn >= 100 ? ' MB' : ' GB';
      weightHTML = '<span class="stat-weight"><i class="fas fa-hdd"></i> ' + weight + wu + '</span>';
    }
    var tagsHTML = (pspTag || catTag) ? '<div class="psp-tags">' + pspTag + catTag + '</div>' : '';
    var imgHTML = thumb ? '<img src="' + thumb + '" alt="' + title + '" loading="lazy" decoding="async"/>' : '<div class="psp-no-image"><i class="fas fa-gamepad"></i></div>';
    return '<div class="psp-card">' +
      '<div class="psp-card-image"><a href="' + link + '">' + imgHTML + '</a>' + tagsHTML + '</div>' +
      '<div class="psp-card-content">' +
        '<h4 class="psp-card-title"><a href="' + link + '">' + title + '</a></h4>' +
        '<div class="psp-stats">' + ratingHTML + weightHTML + '</div>' +
      '</div></div>';
  }

  function getSidebarMax() {
    var w = window.innerWidth;
    return (w >= 768 && w <= 1366) ? 8 : 6;
  }

  function renderSidebarWidget(containerId, feedUrl) {
    var container = document.getElementById(containerId);
    if (!container) return;
    var maxItems = getSidebarMax();
    cachedFetchJson(feedUrl)
      .then(function(data) {
        var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
        if (!entries.length) { container.innerHTML = '<p style="color:#8b8ba8;text-align:center;grid-column:1/-1;">No games.</p>'; return; }
        var html = '';
        entries.slice(0, maxItems).forEach(function(e) { html += generateCardHTML(e); });
        container.innerHTML = html;
        window.observeReveals(container);
      })
      .catch(function() { container.innerHTML = '<p style="color:#8b8ba8;text-align:center;grid-column:1/-1;">Error.</p>'; });
  }

  var sbCount = getSidebarMax();
  renderSidebarWidget('recent-posts-container', '/feeds/posts/default?alt=json&max-results=' + sbCount);
  renderSidebarWidget('popular-posts-container', '/feeds/posts/default?alt=json&max-results=' + sbCount);

  /* SECTION: HOME/LABEL/SEARCH LISTING WITH CUSTOM PAGINATION */
  function getListingFeedUrl() {
    var maxResults = 24; // Número de juegos por página
    var path = window.location.pathname;
    var search = new URLSearchParams(window.location.search);
    var start = parseInt(search.get('start')) || 1;

    var baseUrl = '/feeds/posts/default?alt=json&max-results=' + maxResults + '&start-index=' + start;

    if (path.indexOf('/search/label/') === 0) {
      var label = decodeURIComponent(path.replace('/search/label/', '').replace(/\/$/, ''));
      return '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=' + maxResults + '&start-index=' + start;
    }
    if (path.indexOf('/search') === 0) {
      var q = search.get('q');
      if (q) return '/feeds/posts/default?q=' + encodeURIComponent(q) + '&alt=json&max-results=' + maxResults + '&start-index=' + start;
    }
    var archiveMatch = path.match(/^\/(\d{4})\/(\d{2})\/?$/);
    if (archiveMatch) {
      var year = archiveMatch[1], month = archiveMatch[2];
      return '/feeds/posts/default?published-min=' + year + '-' + month + '-01T00:00:00&published-max=' + year + '-' + month + '-31T23:59:59&alt=json&max-results=' + maxResults + '&start-index=' + start;
    }
    return baseUrl;
  }

  function renderPagination(current, total) {
    var pagContainer = document.getElementById('custom-pagination');
    if (!pagContainer) return;

    if (total <= 1) { pagContainer.innerHTML = ''; return; }

    var html = '<div class="pag-wrapper">';
    html += '<span class="pag-info">Página <strong>' + current + '</strong> de <strong>' + total + '</strong></span>';
    html += '<div class="pag-numbers">';

    // Botón Anterior
    if (current > 1) {
      var prevStart = (current - 2) * 24 + 1;
      html += '<a href="?start=' + prevStart + '" class="pag-btn pag-nav"><i class="fas fa-chevron-left"></i></a>';
    }

    // Números
    var startPage = Math.max(1, current - 4);
    var endPage = Math.min(total, startPage + 9);
    if (endPage - startPage < 9) startPage = Math.max(1, endPage - 9);

    for (var i = startPage; i <= endPage; i++) {
      var startIdx = (i - 1) * 24 + 1;
      var activeClass = (i === current) ? ' active' : '';
      html += '<a href="?start=' + startIdx + '" class="pag-btn' + activeClass + '">' + i + '</a>';
    }

    // Botón Siguiente
    if (current < total) {
      var nextStart = current * 24 + 1;
      html += '<a href="?start=' + nextStart + '" class="pag-btn pag-nav"><i class="fas fa-chevron-right"></i></a>';
    }

    // Última Página
    if (current < total) {
      var lastStart = (total - 1) * 24 + 1;
      html += '<a href="?start=' + lastStart + '" class="pag-btn pag-nav">Última página <i class="fas fa-angle-double-right"></i></a>';
    }

    html += '</div></div>';
    pagContainer.innerHTML = html;
  }

  function renderListingPosts() {
    var container = document.getElementById('posts-container');
    if (!container) return;

    cachedFetchJson(getListingFeedUrl())
      .then(function(data) {
        var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
        var totalPosts = data.feed && data.feed.openSearch$totalResults ? parseInt(data.feed.openSearch$totalResults.$t) : 0;

        // Info label
        var metaInfo = document.getElementById('listing-meta-info');
        if (metaInfo) metaInfo.innerHTML = totalPosts + ' result(s) found';

        if (entries.length === 0) {
          container.innerHTML = '<p style="color:#8b8ba8; text-align:center; grid-column: 1/-1; padding: 40px 20px;">No games found.</p>';
          return;
        }

        var html = '';
        entries.forEach(function(entry) { html += generateCardHTML(entry); });
        container.innerHTML = html;
        window.observeReveals(container);

        // Pagination
        var currentPage = 1;
        var searchParams = new URLSearchParams(window.location.search);
        if (searchParams.has('start')) {
            currentPage = Math.ceil(parseInt(searchParams.get('start')) / 24);
        }
        var totalPages = Math.ceil(totalPosts / 24);
        renderPagination(currentPage, totalPages);
      })
      .catch(function() { 
        container.innerHTML = '<p style="color:#8b8ba8; text-align:center; grid-column: 1/-1; padding: 40px 20px;">Error loading games.</p>'; 
      });
  }

  if (document.getElementById('posts-container')) {
    renderListingPosts();
  }

  /* SECTION: RELATED POSTS (CAROUSEL) */
  (function() {
    var relatedContainer = document.getElementById('related-posts');
    if (!relatedContainer) return;
    var carousel = document.getElementById('related-carousel');
    var btnPrev = document.getElementById('rel-prev');
    var btnNext = document.getElementById('rel-next');
    if (!carousel) return;

    var label = (relatedContainer.getAttribute('data-label') || '').trim();
    var currentUrl = relatedContainer.getAttribute('data-url') || '';

    function normalize(u) {
      return String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '')
        .replace(/\/index\.html$/, '').split('?')[0].split('#')[0].replace(/\/$/, '');
    }
    function getLink(e) {
      for (var i = 0; i < e.link.length; i++) if (e.link[i].rel === 'alternate') return e.link[i].href;
      return '';
    }

    function buildHtml(entries, limit) {
      var cur = normalize(currentUrl);
      var filtered = entries.filter(function(e) { var l = getLink(e); return l && normalize(l) !== cur; });
      return filtered.slice(0, limit || 6).map(generateCardHTML).join('');
    }

    function updateNav() {
      if (!btnPrev || !btnNext) return;
      var maxScroll = carousel.scrollWidth - carousel.clientWidth;
      var atStart = carousel.scrollLeft <= 5;
      var atEnd = carousel.scrollLeft >= maxScroll - 5;
      btnPrev.setAttribute('aria-disabled', atStart ? 'true' : 'false');
      btnNext.setAttribute('aria-disabled', atEnd ? 'true' : 'false');
      btnPrev.disabled = atStart || maxScroll <= 0;
      btnNext.disabled = atEnd || maxScroll <= 0;
    }

    function attachNav() {
      var card = carousel.querySelector('.psp-card'); if (!card) return;
      var step = card.offsetWidth + (parseInt(getComputedStyle(carousel).gap) || 16);
      if (btnPrev && !btnPrev.__b) { btnPrev.__b = 1; btnPrev.addEventListener('click', function() { carousel.scrollBy({ left: -step, behavior: 'smooth' }); }); }
      if (btnNext && !btnNext.__b) { btnNext.__b = 1; btnNext.addEventListener('click', function() { carousel.scrollBy({ left: step, behavior: 'smooth' }); }); }
      carousel.addEventListener('scroll', updateNav, { passive: true });
      window.addEventListener('resize', updateNav);
      updateNav();
    }

    function render(html) {
      if (!html) { relatedContainer.style.display = 'none'; return; }
      carousel.innerHTML = html;
      requestAnimationFrame(function() { carousel.scrollLeft = 0; attachNav(); });
    }

    function fetchRecent() {
      cachedFetchJson('/feeds/posts/default?alt=json&max-results=14')
        .then(function(d) { render(buildHtml((d.feed && d.feed.entry) ? d.feed.entry : [], 6)); })
        .catch(function() { relatedContainer.style.display = 'none'; });
    }
    if (!label) { fetchRecent(); return; }
    cachedFetchJson('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=12')
      .then(function(d) {
        var html = buildHtml((d.feed && d.feed.entry) ? d.feed.entry : [], 6);
        if (html) render(html); else fetchRecent();
      })
      .catch(fetchRecent);
  })();

  /* SECTION: COMMENTS TOGGLE & REPLY */
  window.toggleCommentForm = function() {
    var wrapper = document.getElementById('comment-form-wrapper');
    var btn = document.getElementById('comment-toggle-btn');
    if (!wrapper || !btn) return;
    wrapper.classList.toggle('show');
    if (wrapper.classList.contains('show')) {
      btn.innerHTML = '<i class="fas fa-times"></i><span>Cancel</span>';
      setTimeout(function() { wrapper.scrollIntoView({ behavior: 'smooth', block: 'center' }); }, 100);
    } else {
      btn.innerHTML = '<i class="fas fa-comment-dots"></i><span>Leave a comment</span>';
    }
  };
  window.replyToComment = function(button) {
    var cid = button.getAttribute('data-comment-id');
    var author = button.getAttribute('data-comment-author');
    var notice = document.getElementById('reply-notice');
    var authorSpan = document.getElementById('reply-author-name');
    var editor = document.getElementById('comment-editor');
    var srcEl = document.getElementById('comment-editor-src');
    var formSrc = srcEl ? srcEl.href : null;
    var wrapper = document.getElementById('comment-form-wrapper');
    var toggleBtn = document.getElementById('comment-toggle-btn');
    if (wrapper && !wrapper.classList.contains('show')) {
      wrapper.classList.add('show');
      if (toggleBtn) toggleBtn.innerHTML = '<i class="fas fa-times"></i><span>Cancel</span>';
    }
    if (notice && authorSpan && editor && formSrc) {
      authorSpan.textContent = 'Replying to ' + author;
      notice.classList.add('show');
      editor.src = formSrc + '&parentID=' + cid;
      editor.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };
  window.cancelReply = function() {
    var notice = document.getElementById('reply-notice');
    var editor = document.getElementById('comment-editor');
    var srcEl = document.getElementById('comment-editor-src');
    var formSrc = srcEl ? srcEl.href : null;
    if (notice && editor && formSrc) { notice.classList.remove('show'); editor.src = formSrc; }
  };

  /* SECTION: SHARE */
  window.shareMore = function(btn) {
    var url = btn.getAttribute('data-url');
    var title = btn.getAttribute('data-title') || document.title;
    if (navigator.share) { navigator.share({ title: title, url: url }).catch(function() {}); return; }
    copyToClipboard(url, btn);
  };
  function copyToClipboard(text, btn) {
    function done() {
      var orig = btn.innerHTML;
      btn.classList.add('copied');
      btn.innerHTML = '<i class="fas fa-check"></i><span>Link copied!</span>';
      setTimeout(function() { btn.classList.remove('copied'); btn.innerHTML = orig; }, 1800);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(function() { fallbackCopy(text, done); });
    } else fallbackCopy(text, done);
  }
  function fallbackCopy(text, cb) {
    var ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch(e) {}
    document.body.removeChild(ta);
    if (cb) cb();
  }

  /* SECTION: HERO SEARCH */
  window.handleHeroSubmit = function(e) {
    if (e) e.preventDefault();
    var input = document.getElementById('hero-search-input');
    var catSel = document.getElementById('hero-search-category');
    var q = input ? input.value.trim() : '';
    var cat = catSel ? catSel.value : '';
    if (cat && q) window.location.href = '/search/label/' + encodeURIComponent(cat) + '?q=' + encodeURIComponent(q);
    else if (cat) window.location.href = '/search/label/' + encodeURIComponent(cat);
    else if (q) window.location.href = '/search?q=' + encodeURIComponent(q);
    return false;
  };

  /* SECTION: HERO DESCRIPTION FALLBACK */
  (function() {
    var heroTitle = document.getElementById('hero-description');
    if (!heroTitle) return;
    var currentText = heroTitle.textContent.trim();
    if (!currentText) {
      var metaDesc = document.querySelector('meta[name="description"]') || document.querySelector('meta[property="og:description"]');
      if (metaDesc) {
        var descText = metaDesc.getAttribute('content');
        if (descText) heroTitle.textContent = descText;
      }
    }
  })();

})();
